package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class GroupRoadmapReferenceTest {
 GroupRoadmapStore store;SpaceAuthorizationClient authority;GroupRoadmapReferenceController api;UUID space,link,actor;String key="a".repeat(43);
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();link=ids.next();actor=ids.next();store=mock(GroupRoadmapStore.class);authority=mock(SpaceAuthorizationClient.class);var metrics=new SimpleMeterRegistry();var browser=new RoadmapController(mock(RoadmapStore.class),authority,metrics,"https://localhost:8443");api=new GroupRoadmapReferenceController(store,authority,browser,metrics,key);when(authority.authorize(eq(space),any(),eq("GROUP_ROADMAP_READ"),eq("PRIVATE"),anyString())).thenReturn(actor);}
 MockHttpServletRequest req(){var r=new MockHttpServletRequest("POST","/");r.setSecure(true);r.setContentType("application/json");r.addHeader("Authorization","Bearer "+key);r.setContent(("{\"spaceId\":\""+space+"\",\"roadmapLinkId\":\""+link+"\",\"token\":\""+"b".repeat(43)+"\"}").getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void capabilityMustBeSecureSingletonAndCannotBeBrowserCookieRequest(){for(int mode=0;mode<4;mode++){var r=req();if(mode==0)r.setSecure(false);if(mode==1)r.addHeader("Cookie","__Host-brain_guest=anything");if(mode==2)r.addHeader("Authorization","Bearer "+key);if(mode==3)r.addHeader("Origin","https://localhost:8443");assertThrows(ResponseStatusException.class,()->api.check(r));}verifyNoInteractions(authority,store);}
 @Test void freshGroupAuthorizationReturnsOnlyPinnedReferenceMetadata()throws Exception{var source=new PublicRoadmapStore.Roadmap(link,actor,"PUBLIC","REVIEWED",3,"Pinned","Description",Instant.now().toString(),Instant.now().toString(),List.of(),List.of());var v=new GroupRoadmapStore.Link(link,space,2,"RETIRED","PRIVATE",actor,Instant.now().toString(),Instant.now().toString(),source);when(store.get(space,link)).thenReturn(v);var response=api.check(req());assertEquals("no-store",response.getHeaders().getCacheControl());var ref=(GroupRoadmapReferenceController.Reference)response.getBody();assertEquals(actor,ref.principalId());assertEquals("RETIRED",ref.state());assertEquals(3,ref.sourceVersion());verify(authority).authorize(eq(space),any(),eq("GROUP_ROADMAP_READ"),eq("PRIVATE"),anyString());}
 @Test void invalidOrUnknownBodyAndForeignScopeNeverReadStore(){var r=req();r.addParameter("actorId","bad");assertThrows(ResponseStatusException.class,()->api.check(r));var bad=req();bad.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->api.check(bad));verifyNoInteractions(authority,store);}
}
